/**
 * Validates and normalizes a status-change request from the Join frontend.
 * The browser deliberately sends no recipient address; later nodes load the
 * trusted creator metadata from Firestore.
 */
const input = $input.first().json;
let request = input.body ?? input;
if (typeof request === "string") request = JSON.parse(request);

const statuses = new Set(["triage", "todo", "in-progress", "feedback", "done"]);
const taskId = String(request.taskId || "").trim();
const previousStatus = String(request.previousStatus || "").trim();
const nextStatus = String(request.nextStatus || "").trim();

if (!/^[A-Za-z0-9_-]{1,128}$/.test(taskId)) throw new Error("Invalid task id.");
if (!statuses.has(previousStatus) || !statuses.has(nextStatus)) {
  throw new Error("Invalid board status.");
}
if (previousStatus === nextStatus) throw new Error("The board status did not change.");

return [{ json: { taskId, previousStatus, nextStatus } }];

/**
 * Builds a creator email from trusted Firestore fields.
 * A stale or incomplete request is skipped instead of mailing an address
 * supplied by the public webhook caller.
 */
const fields = $input.first().json.fields ?? {};
const request = $("Validate status change").first().json;
const creatorFields = fields.creator?.mapValue?.fields ?? {};
const creatorType = readString(creatorFields.type);
const recipient = readString(creatorFields.email).trim();
const creatorName = readString(creatorFields.name).trim() || "there";
const title = readString(fields.title).trim() || "Untitled ticket";
const storedStatus = readString(fields.status);
const statusLabels = {
  triage: "Triage",
  todo: "To do",
  "in-progress": "In progress",
  feedback: "Await feedback",
  done: "Done",
};
const shouldNotify =
  ["internal", "external"].includes(creatorType) &&
  /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(recipient) &&
  storedStatus === request.nextStatus;

return [{
  json: {
    shouldNotify,
    recipient,
    subject: "Join ticket moved to " + statusLabels[request.nextStatus],
    message:
      "Hello " + escapeHtml(creatorName) + ",<br><br>" +
      "your ticket <strong>" + escapeHtml(title) + "</strong> moved from " +
      escapeHtml(statusLabels[request.previousStatus]) + " to <strong>" +
      escapeHtml(statusLabels[request.nextStatus]) + "</strong>.<br><br>" +
      "Kind regards,<br>The Join team",
  },
}];

/**
 * Reads a string field from a Firestore REST document.
 * @param {Object} field - Firestore value wrapper.
 * @returns {string} Stored string or an empty fallback.
 */
function readString(field) {
  return typeof field?.stringValue === "string" ? field.stringValue : "";
}

/**
 * Escapes dynamic task data before inserting it into an HTML email.
 * @param {string} value - Untrusted stored display text.
 * @returns {string} HTML-safe text.
 */
function escapeHtml(value) {
  return String(value)
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;")
    .replace(/"/g, "&quot;")
    .replace(/'/g, "&#039;");
}
